        cta: 'Explore decision spreads',
        choose: { name: 'How to Choose a Tarot Reader', href: '/guides/how-to-choose-tarot-reader' },
        secondary: { name: 'Do What Fits', fit: '7-question life matcher', href: '/do-what-fits' },
